import { emit } from "@tauri-apps/api/event";
import { load } from "@tauri-apps/plugin-store";
import { Result } from "better-result";
import { createSignal } from "solid-js";
import type { Locale } from "../i18n";
import { type AppStyle, STYLE_LIST } from "./commands/apps";
import { listAudioDevices } from "./commands/audio";
import { saveBrowserValue, storageError } from "./errors";
import {
	CURRENT_ONBOARDING_VERSION,
	ONBOARDING_STEP_COUNT,
	normalizeOnboardingStep,
} from "./onboarding";
import { DEFAULT_HOLD_TO_SPEAK_HOTKEY, DEFAULT_HOTKEY } from "./hotkeyUtils";

export type Theme = "dark" | "light" | "system";

export interface Settings {
	theme: Theme;
	hotkey: string;
	holdToSpeakHotkey: string;
	selectedMicrophoneId: string | null;
	language: Locale;
	muteMediaWhileRecording: boolean;
	defaultStyle: AppStyle;
	onboardingComplete: boolean;
	onboardingStep: number;
}

const DEFAULT_SETTINGS: Settings = {
	theme: "system",
	hotkey: DEFAULT_HOTKEY,
	holdToSpeakHotkey: DEFAULT_HOLD_TO_SPEAK_HOTKEY,
	selectedMicrophoneId: null,
	language: "en",
	muteMediaWhileRecording: false,
	defaultStyle: "default",
	onboardingComplete: false,
	onboardingStep: 1,
};

const STORE_NAME = "settings.json";

let storeInstance: Awaited<ReturnType<typeof load>> | null = null;

async function getStore() {
	if (!storeInstance) {
		storeInstance = await load(STORE_NAME, {
			defaults: {
				theme: DEFAULT_SETTINGS.theme,
				hotkey: DEFAULT_SETTINGS.hotkey,
				holdToSpeakHotkey: DEFAULT_SETTINGS.holdToSpeakHotkey,
				selectedMicrophoneId: DEFAULT_SETTINGS.selectedMicrophoneId,
				language: DEFAULT_SETTINGS.language,
				muteMediaWhileRecording: DEFAULT_SETTINGS.muteMediaWhileRecording,
				defaultStyle: DEFAULT_SETTINGS.defaultStyle,
				onboardingComplete: DEFAULT_SETTINGS.onboardingComplete,
				onboardingStep: DEFAULT_SETTINGS.onboardingStep,
				onboardingVersion: CURRENT_ONBOARDING_VERSION,
			},
			autoSave: 500,
		});
	}
	return storeInstance;
}

export async function loadSettings(): Promise<Settings> {
	const store = await getStore();
	const theme = await store.get<Theme>("theme");
	const hotkey = await store.get<string>("hotkey");
	const holdToSpeakHotkey = await store.get<string>("holdToSpeakHotkey");
	const selectedMicrophoneId = await store.get<string | null>("selectedMicrophoneId");
	const language = await store.get<Locale>("language");
	const muteMediaWhileRecording = await store.get<boolean>("muteMediaWhileRecording");
	const storedDefaultStyle = await store.get<AppStyle>("defaultStyle");
	const defaultStyle =
		storedDefaultStyle && STYLE_LIST.includes(storedDefaultStyle)
			? storedDefaultStyle
			: DEFAULT_SETTINGS.defaultStyle;
	const onboardingComplete = await store.get<boolean>("onboardingComplete");
	const onboardingStep = await store.get<number>("onboardingStep");
	const onboardingVersion = await store.get<number>("onboardingVersion");
	const normalizedOnboardingStep = normalizeOnboardingStep(
		onboardingStep ?? DEFAULT_SETTINGS.onboardingStep,
		onboardingComplete ?? DEFAULT_SETTINGS.onboardingComplete,
		onboardingVersion ?? 1
	);

	if (normalizedOnboardingStep !== (onboardingStep ?? DEFAULT_SETTINGS.onboardingStep)) {
		await store.set("onboardingStep", normalizedOnboardingStep);
	}
	if ((onboardingVersion ?? 1) !== CURRENT_ONBOARDING_VERSION) {
		await store.set("onboardingVersion", CURRENT_ONBOARDING_VERSION);
	}

	return {
		theme: theme ?? DEFAULT_SETTINGS.theme,
		hotkey: hotkey ?? DEFAULT_SETTINGS.hotkey,
		holdToSpeakHotkey: holdToSpeakHotkey ?? DEFAULT_SETTINGS.holdToSpeakHotkey,
		selectedMicrophoneId: selectedMicrophoneId ?? DEFAULT_SETTINGS.selectedMicrophoneId,
		language: language ?? DEFAULT_SETTINGS.language,
		muteMediaWhileRecording: muteMediaWhileRecording ?? DEFAULT_SETTINGS.muteMediaWhileRecording,
		defaultStyle,
		onboardingComplete: onboardingComplete ?? DEFAULT_SETTINGS.onboardingComplete,
		onboardingStep: normalizedOnboardingStep,
	};
}

export async function saveTheme(theme: Theme): Promise<void> {
	const store = await getStore();
	await store.set("theme", theme);
	saveBrowserValue("voxfusion-theme", theme);
}

export async function saveHotkey(hotkey: string): Promise<void> {
	const store = await getStore();
	await store.set("hotkey", hotkey);
}

export async function saveHoldToSpeakHotkey(hotkey: string): Promise<void> {
	const store = await getStore();
	await store.set("holdToSpeakHotkey", hotkey);
}

export async function saveMicrophone(microphoneId: string | null): Promise<void> {
	const store = await getStore();
	await store.set("selectedMicrophoneId", microphoneId);
}

export async function saveLanguage(language: Locale): Promise<void> {
	const store = await getStore();
	await store.set("language", language);
}

export async function saveMuteMediaWhileRecording(enabled: boolean): Promise<void> {
	const store = await getStore();
	await store.set("muteMediaWhileRecording", enabled);
}

export async function saveDefaultStyle(style: AppStyle): Promise<void> {
	const store = await getStore();
	await store.set("defaultStyle", style);
}

export interface AudioDevice {
	name: string;
	isDefault: boolean;
}

export async function getAudioInputDevices(): Promise<AudioDevice[]> {
	const devices = await listAudioDevices();
	if (Result.isError(devices)) return [];
	return devices.value.map((device) => ({
		name: device.name,
		isDefault: device.is_default,
	}));
}

const [settings, setSettingsInternal] = createSignal<Settings>(DEFAULT_SETTINGS);

export function useSettings() {
	return settings;
}

export async function initSettings(): Promise<void> {
	const loaded = await loadSettings();
	setSettingsInternal(loaded);
	applyTheme(loaded.theme);
	saveBrowserValue("voxfusion-theme", loaded.theme);
}

export async function updateTheme(theme: Theme): Promise<void> {
	await saveTheme(theme);
	setSettingsInternal((prev) => ({ ...prev, theme }));
	applyTheme(theme);
	await emit("settings-changed");
}

export async function updateHotkey(hotkey: string): Promise<void> {
	await saveHotkey(hotkey);
	setSettingsInternal((prev) => ({ ...prev, hotkey }));
	await emit("settings-changed");
}

export async function updateHoldToSpeakHotkey(hotkey: string): Promise<void> {
	await saveHoldToSpeakHotkey(hotkey);
	setSettingsInternal((prev) => ({ ...prev, holdToSpeakHotkey: hotkey }));
	await emit("settings-changed");
}

export async function updateMicrophone(microphoneId: string | null): Promise<void> {
	await saveMicrophone(microphoneId);
	setSettingsInternal((prev) => ({ ...prev, selectedMicrophoneId: microphoneId }));
	await emit("settings-changed");
}

export async function updateLanguage(
	language: Locale,
	setLocale: (locale: Locale) => void
): Promise<void> {
	await saveLanguage(language);
	setSettingsInternal((prev) => ({ ...prev, language }));
	setLocale(language);
}

export async function updateMuteMediaWhileRecording(enabled: boolean): Promise<void> {
	await saveMuteMediaWhileRecording(enabled);
	setSettingsInternal((prev) => ({ ...prev, muteMediaWhileRecording: enabled }));
	await emit("settings-changed");
}

export async function updateDefaultStyle(style: AppStyle): Promise<void> {
	await saveDefaultStyle(style);
	setSettingsInternal((prev) => ({ ...prev, defaultStyle: style }));
	await emit("settings-changed");
}

function applyTheme(theme: Theme): void {
	const root = document.documentElement;

	if (theme === "system") {
		const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
		root.classList.toggle("dark", prefersDark);
	} else {
		root.classList.toggle("dark", theme === "dark");
	}
}

if (typeof window !== "undefined") {
	window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => {
		const currentSettings = settings();
		if (currentSettings.theme === "system") {
			applyTheme("system");
		}
	});
}

export async function updateOnboardingStep(step: number): Promise<void> {
	const store = await getStore();
	await store.set("onboardingStep", step);
	await store.save();
	setSettingsInternal((prev) => ({ ...prev, onboardingStep: step }));
}

export async function markOnboardingComplete(): Promise<void> {
	setSettingsInternal((prev) => ({ ...prev, onboardingComplete: true, onboardingStep: 1 }));
	const result = await Result.tryPromise({
		try: async () => {
			const store = await getStore();
			await store.set("onboardingComplete", true);
			await store.set("onboardingStep", 1);
			await store.save();
			await emit("settings-changed");
		},
		catch: (cause) => storageError("persist onboarding completion", cause),
	});
	if (Result.isError(result)) {
		console.error("Failed to persist onboarding completion:", result.error);
	}
}

export async function resetOnboarding(): Promise<void> {
	const store = await getStore();
	await store.set("onboardingComplete", false);
	setSettingsInternal((prev) => ({ ...prev, onboardingComplete: false }));
}

export async function resumeOnboardingAt(step: number): Promise<void> {
	const clamped = Math.min(Math.max(step, 1), ONBOARDING_STEP_COUNT);
	setSettingsInternal((prev) => ({
		...prev,
		onboardingComplete: false,
		onboardingStep: clamped,
	}));
	const result = await Result.tryPromise({
		try: async () => {
			const store = await getStore();
			await store.set("onboardingComplete", false);
			await store.set("onboardingStep", clamped);
			await store.save();
			await emit("settings-changed");
		},
		catch: (cause) => storageError("persist onboarding resume", cause),
	});
	if (Result.isError(result)) {
		console.error("Failed to persist onboarding resume:", result.error);
	}
}

